def repartir_stock_existente(apps, schema_editor):
    """Reparte el stock que ya existía entre las bodegas.

    Para cada producto: lo que entró por compras a una bodega menos lo que salió
    por consumos de esa bodega. Lo que sobra (stock inicial sin compra asociada)
    queda en la primera bodega activa. La suma siempre queda igual a stock_actual.
    """
    Bodega = apps.get_model("inventario", "Bodega")
    Producto = apps.get_model("inventario", "Producto")
    StockBodega = apps.get_model("inventario", "StockBodega")
    DetalleDocumento = apps.get_model("inventario", "DetalleDocumento")
    Consumo = apps.get_model("inventario", "Consumo")

    bodegas = list(Bodega.objects.order_by("id"))
    if not bodegas:
        return
    principal = next((b for b in bodegas if b.estado), bodegas[0])

    for producto in Producto.objects.all():
        total = producto.stock_actual
        if total <= 0:
            continue
        por_bodega = {}
        for d in DetalleDocumento.objects.filter(producto=producto).select_related("documento"):
            b = d.documento.bodega_id
            por_bodega[b] = por_bodega.get(b, 0) + d.cantidad
        for c in Consumo.objects.filter(producto=producto).exclude(estado="ANULADO"):
            por_bodega[c.bodega_id] = por_bodega.get(c.bodega_id, 0) - c.cantidad_retirada
        por_bodega = {b: max(v, 0) for b, v in por_bodega.items()}

        resto = total - sum(por_bodega.values())
        if resto >= 0:
            por_bodega[principal.id] = por_bodega.get(principal.id, 0) + resto
        else:  # datos inconsistentes: se descuenta de las bodegas con más stock
            exceso = -resto
            for b in sorted(por_bodega, key=por_bodega.get, reverse=True):
                quitar = min(por_bodega[b], exceso)
                por_bodega[b] -= quitar
                exceso -= quitar
                if exceso <= 0:
                    break

        for b, cantidad in por_bodega.items():
            if cantidad > 0:
                StockBodega.objects.create(bodega_id=b, producto=producto, cantidad=cantidad)


